import sys

def main():
    data = sys.stdin.read().split()
    n, x = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))
    l, r = 0, n - 1
    best = None
    while l < r:
        s = a[l] + a[r]
        key = (abs(s - x), s)
        if best is None or key < best:
            best = key
        if s < x:
            l += 1
        elif s > x:
            r -= 1
        else:
            break
    print(best[1])

